var aiUi=require("$:/plugins/huwiki/ai/i18n.js");
/*\
title: $:/plugins/huwiki/ai/image-view-widget.js
type: application/javascript
module-type: widget

Render normal HUWiki AV references through the existing authenticated playback API.
\*/
(function(){
"use strict";
var Widget=require('$:/core/modules/widgets/widget.js').widget;
var images=require('$:/plugins/huwiki/ai/image-replies.js');
function ImageView(tree,options){this.initialise(tree,options);}
ImageView.prototype=new Widget();
ImageView.prototype.render=function(parent,next){
  this.parentDomNode=parent;this.computeAttributes();this.source=this.getAttribute('source',this.getVariable('currentTiddler'));
  var t=this.wiki.getTiddler(this.source),box=this.document.createElement('div');box.className='huw-ai-output-image';parent.insertBefore(box,next);this.domNodes=[box];
  if(!t||!t.fields['av-file-id']){box.textContent=aiUi.text('Billedtiddleren mangler en AV-reference.');return;}
  var img=this.document.createElement('img');img.alt=t.fields.caption||this.source;box.appendChild(img);
  var status=this.document.createElement('p');status.textContent=aiUi.text('Henter fra AV…');box.appendChild(status);
  var retry=this.document.createElement('button');retry.textContent=aiUi.text('Hent billede igen');box.appendChild(retry);
  var ref={title:this.source,fileId:t.fields['av-file-id']};
  function load(){retry.disabled=true;images.loadAvImage($tw.wiki,ref).then(function(url){img.src=url;status.textContent='';retry.hidden=true;},function(e){status.textContent=e.message||String(e);retry.disabled=false;retry.hidden=false;});}
  retry.addEventListener('click',load);load();
};
ImageView.prototype.refresh=function(changed){var attrs=this.computeAttributes();if(attrs.source||(changed&&changed[this.source])){this.refreshSelf();return true;}if(changed&&changed["$:/language"]){var root=this.domNodes&&this.domNodes[0],button=root&&root.querySelector("button"),status=root&&root.querySelector("p");if(button)button.textContent=aiUi.text("Hent billede igen");if(status)status.textContent=aiUi.message(status.textContent);if(root&&!button)root.textContent=aiUi.message(root.textContent);return true;}return false;};
exports['huwiki-ai-image']=ImageView;
})();
